import { HpaCore, type EmscriptenFactory, type EmscriptenModule } from "./hpaCore.js";

/** What the generated Emscripten factory accepts (a subset of Emscripten's Module arguments). */
type GeneratedFactory = (moduleArg?: { locateFile?: (path: string, scriptDirectory: string) => string }) => Promise<EmscriptenModule>;

// The module is generated by `npm run wasm:build` into ./generated (git-ignored). import.meta.glob
// yields an empty object when it has not been built, so the app still compiles and a missing module
// becomes a clear runtime error instead of a build failure. The globs are lazy: nothing is fetched
// until loadHpaCore() runs inside the worker.
const generatedFactory = import.meta.glob<{ default: GeneratedFactory }>("./generated/hpa_core.js");
// The URL of the .wasm file as emitted by Vite. Emscripten's own `new URL("hpa_core.wasm", import.meta.url)`
// is not recognised by Vite's asset pipeline, so the browser build would otherwise miss the file.
const generatedWasmUrl = import.meta.glob<string>("./generated/hpa_core.wasm", { query: "?url", import: "default" });

/** True when `npm run wasm:build` has produced the module (it is not checked for validity here). */
export const isModuleBuilt = (): boolean => "./generated/hpa_core.js" in generatedFactory;

export const MODULE_NOT_BUILT_MESSAGE =
  "the WebAssembly module has not been built; run `npm run wasm:build` (see cpp/README.md)";

/** Browsers and Web Workers fetch the .wasm by URL; Node.js (tests) lets the glue read the file itself. */
const runsInBrowser = (): boolean => "window" in globalThis || "WorkerGlobalScope" in globalThis;

/** Loads and instantiates the WebAssembly module asynchronously. Rejects if it is missing or invalid. */
export async function loadHpaCore(options: { maxEvents?: number } = {}): Promise<HpaCore> {
  const loadFactory = generatedFactory["./generated/hpa_core.js"];
  if (!loadFactory) throw new Error(MODULE_NOT_BUILT_MESSAGE);
  const loadWasmUrl = generatedWasmUrl["./generated/hpa_core.wasm"];
  const wasmUrl = loadWasmUrl ? await loadWasmUrl() : undefined;
  const { default: factory } = await loadFactory();
  const instantiate: EmscriptenFactory = () =>
    factory(runsInBrowser() && wasmUrl ? { locateFile: (path) => (path.endsWith(".wasm") ? wasmUrl : path) } : {});
  return HpaCore.create(instantiate, options);
}
